import React from "react";
import ReactDOM from "react-dom/client";

function normalize(code: string) {
  // remove imports
  code = code.replace(/^import .*$/gm, "");

  // convert export default function
  code = code.replace(
    /export default function (\w+)/,
    "function $1"
  );

  // 🔥 replace common UI components with divs
  const components = [
    "Card",
    "CardHeader",
    "CardContent",
    "CardTitle",
    "CardDescription",
  ];

  components.forEach((name) => {
    const open = new RegExp(`<${name}`, "g");
    const close = new RegExp(`</${name}>`, "g");

    code = code.replace(open, "<div");
    code = code.replace(close, "</div>");
  });

  // 🔥 ensure function returns JSX
  code += "\nreturn typeof Page !== 'undefined' ? Page : (() => <div>No Preview</div>);";

  return code;
}

async function boot() {
  const rootEl = document.getElementById("root")!;
  const root = ReactDOM.createRoot(rootEl);

  const params = new URLSearchParams(window.location.search);
  const projectId = params.get("projectId");

  if (!projectId) {
    root.render(<div style={{ padding: 20 }}>❌ Missing projectId</div>);
    return;
  }

  try {
    const listRes = await fetch(
      `http://localhost:3000/api/dev/fs/list?projectId=${projectId}`
    );

    const listJson = await listRes.json();

    const entry =
      listJson.files.find((f: string) => f.endsWith("app/page.tsx")) ||
      listJson.files.find((f: string) => f.endsWith("page.tsx"));

    if (!entry) {
      root.render(<div style={{ padding: 20 }}>❌ No page.tsx</div>);
      return;
    }

    const fileRes = await fetch(
      `http://localhost:3000/api/dev/fs/read?projectId=${projectId}&file=${encodeURIComponent(entry)}`
    );

    const fileJson = await fileRes.json();

    let code = fileJson.content;

    code = normalize(code);

    const App = new Function("React", code)(React);

    root.render(
      <div style={{ padding: 20 }}>
        <App />
      </div>
    );

  } catch (err: any) {
    root.render(
      <pre style={{ color: "red", padding: 20 }}>
        {String(err.message)}
      </pre>
    );
  }
}

boot();
EOF

